from collections import Counter


def transform(grid):
    """Highlight background-colored omissions in repeated foreground row-patterns."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # For each foreground color, contiguous rows containing it form one copy of a
    # pattern. Repeated copies align horizontally; use the most complete copy as
    # the reference and mark background cells missing from the other copies.
    for color in set(v for row in grid for v in row if v != background):
        active = [any(v == color for v in row) for row in grid]
        runs = []
        r = 0
        while r < h:
            if not active[r]:
                r += 1
                continue
            start = r
            while r < h and active[r]:
                r += 1
            runs.append((start, r))

        by_height = {}
        for start, end in runs:
            by_height.setdefault(end - start, []).append((start, end))
        for height, blocks in by_height.items():
            if len(blocks) < 2:
                continue
            ref_start, ref_end = max(
                blocks,
                key=lambda b: (sum(v == color for row in grid[b[0]:b[1]] for v in row), -b[0]),
            )
            for start, end in blocks:
                if start == ref_start:
                    continue
                for dr in range(height):
                    rr, ref_r = start + dr, ref_start + dr
                    for c in range(w):
                        if grid[rr][c] == background and grid[ref_r][c] != background:
                            out[rr][c] = 1
    return out
